"""Articles and reading paths for the agency journal."""

POSTS = (
    ('what-is-geo/', 'Что такое GEO и чем оно отличается от SEO?',
     'GEO, или Generative Engine Optimization, помогает бренду быть заметным в ответах нейросетей, когда покупатели ищут продукты или сравнивают компании.', 'prism', '2026-11-04'),
    ('blog/mention-or-recommendation/', 'Чем упоминание бренда отличается от рекомендации?',
     'Упоминание означает, что нейросеть назвала компанию. При рекомендации она предлагает выбрать или рассмотреть её для конкретной задачи.', 'mention', '2026-11-18'),
    ('blog/why-ai-recommends-competitors/', 'Почему ИИ рекомендует конкурентов?',
     'ИИ может предложить конкурента из-за условий конкретного запроса или сведений из доступных источников. Начните с довода, который видит покупатель, и проверьте, чем он подтверждён.', 'choice', '2026-11-18'),
)

TOPICS = {'prism': 'Основы GEO', 'mention': 'Упоминания бренда', 'choice': 'Конкуренты'}


def cover_art(motif):
    if motif == 'prism':
        graphic = '<div class="folio-search">Поиск<i></i><i></i><i></i></div><div class="folio-answer">Ответ<i></i><i></i><b>Бренд</b></div>'
    elif motif == 'mention':
        graphic = '<div class="folio-quote"><i></i><b>Бренд</b><i></i><i></i><em>почему подходит</em></div>'
    else:
        graphic = '<div class="folio-compare"><div><b>Ваш бренд</b><i></i><i></i></div><div><b>Конкурент</b><i></i><i></i></div></div>'
    return f'<div class="folio-art folio-{motif}" aria-hidden="true">{graphic}</div>'


def journal():
    cards = []
    for route, title, lead, motif, date in POSTS:
        action = 'Читать о GEO' if motif == 'prism' else 'Читать статью'
        cards.append(f'''<article class="journal-entry entry-{motif}"><a href="{{PRE}}{route}">
        {cover_art(motif)}<div class="journal-entry-copy"><div class="entry-meta"><span>{TOPICS[motif]}</span>
        <time datetime="{date}">{date[8:]}.{date[5:7]}.{date[:4]}</time></div>
        <h2>{title}</h2><p>{lead}</p><span class="article-action">{action} ↗</span></div></a></article>''')
    return '''<div class="journal-hub wrap"><header><h1>Блог о GEO</h1>
    <p class="short-answer">Что покупатели узнают о компании в нейросетях и как маркетингу работать с этим каналом. Начните с основ или выберите вопрос, который возник при разборе ответов о вашем бренде.</p></header>
    <div class="journal-board">'''+''.join(cards)+'''</div></div><aside class="journal-help"><div class="wrap"><h2>Хотите проверить свой бренд?</h2><p>Посмотрите, как в отчёте выглядят упоминания, источники и ссылки.</p><a class="btn primary" href="{PRE}audit/#observations">Образец GEO-аудита ↗</a></div></aside>'''


def part(title, body, anchor=None):
    fragment = f' id="{anchor}"' if anchor else ''
    return f'<section class="a-prose-section"{fragment}><h2>{title}</h2>{body}</section>'


def geo_article():
    return ''.join((
        part('Как бренд появляется в ответе', '''<p>GEO расшифровывается как Generative Engine Optimization. У покупателя есть задача, у нейросети есть возможность сразу предложить несколько решений. Маркетингу важно, встретится ли среди них компания и что человек успеет узнать о ней до перехода на сайт.</p>
        <p>При оценке видимости различают появление названия в тексте, включение сайта в список источников и прямую ссылку на страницу. Сайт порой служит источником сведений для ответа, в котором читатель вообще не увидит название компании.</p>'''),
        part('GEO, SEO и AEO', '''<dl class="reader-definitions"><div><dt>SEO</dt><dd>Помогает людям найти страницу в поиске. О результате судят по видимости в выдаче, кликам и действиям на сайте.</dd></div>
        <div><dt>GEO</dt><dd>Помогает бренду участвовать в выборе внутри нейросети. Важны темы, по которым его называют, точность описания и ссылки в ответе.</dd></div>
        <div><dt>AEO</dt><dd>Answer Engine Optimization. Здесь акцент на том, насколько материал отвечает на вопрос пользователя. На практике эта работа пересекается и с SEO, и с GEO.</dd></div></dl>
        <p>Для AI-функций поиска Google действуют обычные требования к доступности страниц. Специальная разметка для попадания в такие ответы не требуется. <a rel="nofollow" href="https://developers.google.com/search/docs/appearance/ai-features">Правила Google Search Central</a>.</p>'''),
        part('Видимость сайта в Google, ChatGPT и Алисе', '''<p>В Google требования к участию в AI Overviews и AI Mode опираются на обычную поисковую доступность: страница должна быть проиндексирована и подходить для показа сниппета.</p>
        <p>Для показа материалов в поиске ChatGPT OpenAI рекомендует открыть доступ роботу OAI-SearchBot. Доступ к поиску и использование материалов для обучения управляются отдельно. <a rel="nofollow" href="https://developers.openai.com/api/docs/bots">Документация OpenAI о краулерах</a>.</p>
        <p>В Яндекс Вебмастере можно увидеть примеры запросов и страниц, которые Алиса AI использовала как источники. Отчёт описывает видимость сайта в ответах Алисы AI в Поиске. Для вывода о рекомендациях бренда нужно смотреть текст ответа. <a rel="nofollow" href="https://yandex.ru/support/webmaster/ru/service/alice-answers">Справка Яндекс Вебмастера</a>.</p>''', 'platform-visibility'),
        part('На что может повлиять компания', '''<p>Компания отвечает за факты, которые публикует о себе. Насколько ясно на сайте описано предложение? Совпадают ли условия на разных страницах? Может ли покупатель проверить преимущество, которое обещает бренд?</p>
        <p>Кроме официального сайта есть внешние публикации. Стоит выяснить, какие из них встречаются рядом с вашим брендом и совпадает ли описание с действительностью. Этот разбор помогает решить, что делать сначала: обновить страницу, уточнить публичную информацию или подготовить материал о продукте.</p>'''),
        part('Как читать результат', '''<p>Сравнивайте ответы по вопросам об одной и той же потребности. Вопрос с названием бренда помогает увидеть его репутацию. Вопрос без названия показывает, попадёте ли вы в выбор покупателя, который ещё не знаком с компанией.</p>
        <p>Кликам, заявкам и заказам нужны свои источники данных. В <a href="{PRE}cases/fashion/">кейсе модного бренда</a> переходы из нейросетей на два сайта показаны отдельно от кликов из поиска Google. Складывать эти показатели как один результат GEO было бы ошибкой.</p>'''),
        part('С чего начать', '''<p>Назовите одно направление, по которому нужны новые клиенты. Запишите, какие требования определяют выбор, по каким вопросам вас сравнивают и с кем. Тогда станет ясно, какие ответы действительно стоит проверять.</p>
        <p><a href="{PRE}why-geo/">Оценить пользу GEO для своего бренда</a> · <a href="{PRE}audit/#observations">Посмотреть образец отчёта</a></p>'''),
        part('Когда переходить к продвижению', '''<p>По итогам аудита бизнесу важно выбрать реальное изменение. Какой вопрос влияет на выбор клиента? Где он встречает неверные сведения? Какую страницу или публикацию стоит обновить? Если ответ есть, у проекта появляется цель для следующего замера. Отчёт без такого решения может остаться просто списком упоминаний.</p>'''),
    ))


def mention_article():
    return ''.join((
        part('Одно название, разные роли', '''<p>Представьте, что в двух ответах нейросеть назвала вашу компанию по одному разу. В первом она перечислила участников рынка. Во втором объяснила, почему условия компании подходят под запрос покупателя. В статистике это два упоминания. Для человека, который собирается сделать выбор, между ними большая разница.</p>
        <dl class="reader-definitions"><div><dt>Упоминание</dt><dd>Читатель видит название. Отношение нейросети к бренду может быть положительным, нейтральным или критическим.</dd></div><div><dt>Сравнение</dt><dd>Продукт попал в круг возможных вариантов. В ответе есть критерий, по которому его сопоставляют с другими.</dd></div><div><dt>Рекомендация</dt><dd>Нейросеть предлагает рассмотреть или выбрать продукт для задачи покупателя. Важно, каким доводом она это объясняет.</dd></div></dl>'''),
        part('Как различить их в одном ответе', '''<figure class="reader-example"><figcaption>Учебный пример · сервис рассылок</figcaption>
        <blockquote>«У сервиса „Лист“ есть шаблоны писем. Для команды, которой нужно согласовывать рассылку перед отправкой, я бы выбрал „Письмо“: там есть отдельная роль редактора».</blockquote>
        <p>«Лист» назван в справке. «Письмо» рекомендовано, потому что в ответе есть совет и причина выбора. Обе компании вымышлены.</p></figure>''', 'example'),
        part('Почему нужен исходный вопрос', '''<p>Если человек сам упомянул компанию и попросил рассказать об условиях, название почти наверняка появится в ответе. Такой диалог пригодится для проверки фактов. Из него трудно узнать, вспомнила бы нейросеть бренд сама.</p>
        <p>При вопросе без названия можно увидеть круг предложенных компаний. Прочитайте весь ответ: кому именно подходит предложение, есть ли у совета условие и что нейросеть предлагает сделать дальше. По одной выделенной фразе легко пропустить оговорку.</p>'''),
        part('Чей сайт откроет покупатель', '''<p>Даже прямой совет рассмотреть бренд иногда ведёт к чужому обзору. И наоборот, нейросеть может взять цифры с вашего сайта для разбора рынка и перечислить другие компании.</p>
        <p>Для отдела маркетинга важно, куда ведёт ссылка и сможет ли покупатель проверить там условия. Если в источниках указан каталог партнёра, а совет звучит как рекомендация бренда, это два разных наблюдения. В <a href="{PRE}cases/winline/#sources">аудите WINLINE</a> отдельно учитывали название в тексте, домен в источниках и адрес страницы. У каждого такого наблюдения был свой смысл.</p>'''),
        part('Что обсудить с маркетингом', '''<p>Попросите показать рядом вопрос, полный ответ и страницу, на которую тот ссылается. Какое обещание прочитал покупатель? Может ли компания его выполнить? Если продукт описан точно, стоит развивать темы, где бренд уже рассматривают. Если в совете ошибка, первым делом важна точность публичных сведений.</p>
        <p>На <a href="{PRE}audit/#sample-board">интерактивном примере аудита</a> можно переключать признаки и увидеть, как один и тот же ответ меняет картину отчёта.</p>'''),
        part('Где заканчивается вывод об ответе', '''<p>Рекомендация описывает то, что увидел покупатель. Чтобы узнать о результате для бизнеса, понадобится другой факт: переход на сайт, обращение или заказ. Эти сведения можно связать, если источник сохранился в аналитике или сам клиент сообщил, где впервые узнал о вас.</p>'''),
    ))


def competitor_article():
    return ''.join((
        part('Начните с условий выбора', '''<p>В ответе покупателю важны причины, по которым предложена конкретная компания. Возьмите формулировку вопроса целиком, включая уточнения из предыдущих сообщений. Бюджет, география, совместимость и требования к обслуживанию способны изменить круг подходящих продуктов.</p>
        <p>Если ваш продукт подходит, выясните, какой довод нейросеть приводит в пользу конкурента. Этот довод можно проверить. Если продукт действительно не соответствует условиям, спор за такое упоминание вряд ли поможет продажам.</p>'''),
        part('Найдите основание для сравнения', '''<p>Откройте источники, которые видит покупатель. Есть ли там страница конкурента, независимый обзор или подборка? Прочитайте, откуда взялось утверждение о продукте, есть ли у материала дата и соответствует ли сравнение текущим условиям.</p>
        <p>Если источники не показаны, причину выбора остаётся считать гипотезой. В отчёте можно уверенно зафиксировать сам ответ и доводы в тексте. Установить, какую именно публикацию использовала модель, по одному упоминанию нельзя.</p>'''),
        part('Проверьте, повторяется ли наблюдение', '''<p>Один ответ годится как повод для проверки. Несколько сопоставимых ответов помогают увидеть, ограничена ли проблема одной формулировкой или повторяется по целой теме. Разделяйте вопросы с названием компании и без него.</p>
        <p>В <a href="{PRE}cases/winline/#panel">проекте WINLINE</a> мы сравнили ответы пяти моделей на один набор вопросов. Так у команды была возможность вернуться от общего результата к теме, конкретному ответу и его источникам.</p>'''),
        part('Как проверить довод на конкретном примере', '''<figure class="reader-example"><figcaption>Учебный пример · доставка оборудования</figcaption>
        <blockquote>«Я бы выбрал компанию „Контур“: она привозит оборудование в выходные».</blockquote>
        <p>Условия доставки можно проверить на странице услуги или у менеджера. Если ваш бизнес тоже доставляет в выходные, но об этом знают только сотрудники, на странице есть что уточнить. Если доставка доступна по будням, у конкурента в этой ситуации есть реальное преимущество. «Контур» в примере вымышлен.</p></figure>''', 'example'),
        part('Как выбрать следующий шаг', '''<dl class="reader-definitions"><div><dt>Конкурент точнее отвечает на запрос</dt><dd>Проверьте, раскрыта ли на вашей странице характеристика, которая повлияла на выбор. Уточните её, если она действительно относится к вашему продукту.</dd></div>
        <div><dt>О бренде пишут по-разному</dt><dd>Найдите расхождение между официальным сайтом и публикацией. Решите, какой источник требует обновления и кто может подтвердить верные данные.</dd></div>
        <div><dt>Тем много, приоритет неясен</dt><dd>Начните с тех, по которым покупатели уже обращаются в отдел продаж. <a href="{PRE}audit/#competitors">Сравнение в GEO-аудите</a> покажет, где с вами конкурируют за один и тот же спрос.</dd></div></dl>'''),
        part('Как понять, помогли ли изменения', '''<p>Вернитесь к тем же вопросам после обновления материалов. Изменился ли довод в пользу конкурента? Появился ли ваш бренд там, где он уместен? Отдельно отметьте случаи, в которых нейросеть стала ссылаться на официальную страницу. Так в результатах будут видны и успехи, и оставшиеся задачи.</p>'''),
    ))
